/**
 * Håndterer vedleggsfeil før payload-transformasjon.
 *
 * Leser entry.metadata.failed_files — satt av prune-noden og akkumulert
 * av Classify attachments og Fetch WaSOS files på GET-siden.
 *
 * For WaSOS-destinasjoner er alle feil kjent nå (ingen upload-steg følger).
 * Patcher entry.text med en mottakernotis som viser korrekt antall,
 * og brenner avsendernotifikasjon via link-out.
 *
 * For Rayvn-destinasjoner utsettes begge deler til etter upload i
 * POST to Rayvn log — upload-feil er ikke kjent ennå.
 *
 * Output 1: msg fortsetter (alltid)
 * Output 2: notifikasjonspayload for WaSOS-destinasjoner (null ellers)
 */
const entry  = msg.entry;
const failed = entry.metadata.failed_files || [];

// Ingen feil — ingenting å gjøre uansett destinasjon
if (failed.length === 0) return [msg, null];

// Rayvn: utsett til etter upload der det komplette feilbildet er kjent
if (entry.metadata.target.client_system === "rayvn") return [msg, null];

// WaSOS (og evt. fremtidige ikke-upload-systemer): alle feil kjent nå
const succeeded = entry.files.length;
const total     = succeeded + failed.length;
const notice    = " [" + failed.length + "/" + total
                + " vedlegg ikke overført. Avsender mottar instruks om alternativ håndtering]";

// Legg notisen på entry.text — Bridge to WaSOS bruker entry.text som content
entry.text = (entry.text || "") + notice;

const notification = {
    payload: {
        entry_id:     entry.id,
        failed_files: failed,
        entry_author: entry.author,
        metadata:     entry.metadata
    }
};

return [msg, notification];

/**
 * Tilpasser bridge-entry til WaSOS sitt meldingsformat.
 *
 * Setter msg.metadata = entry.metadata — de to er samme objekt herfra.
 * WaSOS støtter ikke vedlegg via API, så files er alltid tom.
 * entry.text er allerede patcha av Handle failed files om nødvendig.
 */
const entry  = msg.entry;
const source = entry.metadata.source;
const utils  = global.get("utils");

msg.metadata = entry.metadata;
msg.payload  = {
    content:        entry.text,
    callsign:       `${utils.build_callsign(source)} ${entry.author}`,
    isLocation:     false,
    replyMessageId: null,
    files:          []
};

return msg;

/**
 * Tilpasser bridge-entry til Rayvn sitt logg-entry-format.
 *
 * Setter msg.metadata = entry.metadata — de to er samme objekt herfra.
 * Upload files to Rayvn skriver upload-feil direkte til msg.metadata.failed_files,
 * som dermed også reflekteres i entry.metadata (samme referanse).
 *
 * entry.files sendes med — Upload-noden erstatter disse med Rayvn fil-IDer.
 * entry.text patches ikke her; det gjøres av Patch receiver text etter upload
 * når det komplette feilbildet er kjent.
 */
const entry  = msg.entry;
const source = entry.metadata.source;
const utils  = global.get("utils");

msg.metadata = entry.metadata;
msg.payload  = {
    text:             `${utils.build_callsign(source)} ${entry.author}: ${entry.text || ""}`,
    keyEvent:         false,
    releasedInfo:     false,
    loggedByFullName: `${utils.build_callsign(source)} ${entry.author}`,
    labels:           [],
    files:            entry.files || []
};

return msg;
